package com.campuslibrary.model;

import java.time.LocalDateTime;

/** Model (generated by scripts/gen_models.py). Plain JavaBean so it can be read from JSP/EL. */
public class Book {
    private long id;
    private long categoryId;
    private String title;
    private String author;
    private String isbn;
    private String description;
    private Integer publishedYear;
    private String coverUrl;
    private int copiesTotal;
    private int copiesAvailable;
    private LocalDateTime createdAt;
    private String categoryName;
    private String categoryColor;
    private double avgRating;
    private int reviewCount;
    private int loanCount;
    private boolean favorite;

    public long getId() { return id; }
    public void setId(long v) { this.id = v; }
    public long getCategoryId() { return categoryId; }
    public void setCategoryId(long v) { this.categoryId = v; }
    public String getTitle() { return title; }
    public void setTitle(String v) { this.title = v; }
    public String getAuthor() { return author; }
    public void setAuthor(String v) { this.author = v; }
    public String getIsbn() { return isbn; }
    public void setIsbn(String v) { this.isbn = v; }
    public String getDescription() { return description; }
    public void setDescription(String v) { this.description = v; }
    public Integer getPublishedYear() { return publishedYear; }
    public void setPublishedYear(Integer v) { this.publishedYear = v; }
    public String getCoverUrl() { return coverUrl; }
    public void setCoverUrl(String v) { this.coverUrl = v; }
    public int getCopiesTotal() { return copiesTotal; }
    public void setCopiesTotal(int v) { this.copiesTotal = v; }
    public int getCopiesAvailable() { return copiesAvailable; }
    public void setCopiesAvailable(int v) { this.copiesAvailable = v; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime v) { this.createdAt = v; }
    public String getCategoryName() { return categoryName; }
    public void setCategoryName(String v) { this.categoryName = v; }
    public String getCategoryColor() { return categoryColor; }
    public void setCategoryColor(String v) { this.categoryColor = v; }
    public double getAvgRating() { return avgRating; }
    public void setAvgRating(double v) { this.avgRating = v; }
    public int getReviewCount() { return reviewCount; }
    public void setReviewCount(int v) { this.reviewCount = v; }
    public int getLoanCount() { return loanCount; }
    public void setLoanCount(int v) { this.loanCount = v; }
    public boolean isFavorite() { return favorite; }
    public void setFavorite(boolean v) { this.favorite = v; }

    public boolean isAvailable() { return copiesAvailable > 0; }
    public int getPattern() { return (int) (id % 4); }
    public String getAvgRatingText() { return String.format(java.util.Locale.ROOT, "%.1f", avgRating); }
}
